def read(name):return pd.read_csv(OUT/name,float_precision='round_trip')
def md(d):
 def val(v):
  if isinstance(v,(float,np.floating)):return 'N/A' if not np.isfinite(v) else f'{v:.7g}'
  return str(v).replace('|','/').replace('\n',' ')
 return '\n'.join(['| '+' | '.join(map(str,d.columns))+' |','| '+' | '.join(['---']*len(d.columns))+' |']+['| '+' | '.join(val(v) for v in r)+' |' for r in d.itertuples(index=False,name=None)])
def side(d,keys,value):
 d=d.copy();d['result']=d.apply(value,axis=1);assert not d.duplicated(keys+['input_set']).any()
 return d.pivot(index=keys,columns='input_set',values='result').reindex(columns=['O','C']).reset_index().fillna('N/A')
def pairfmt(r):return f"Δ={r.theta_hat:.6g}; seed SD={r.seed_delta_sd:.4g}; wins={int(r.seed_wins)}/{int(r.n_seeds)}; q={r.p_holm_3h:.5g}"
def meanfmt(m,sd):return f'{m:.7g} ± {sd:.4g}' if np.isfinite(sd) else f'{m:.7g}; SD N/A'
def link(name):return f'[{name}]({OUT/name})'

